Data.M1LogicRequestSpeedCmd_Pct   := M1LogicRequestSpeedCmd_Pct;
Data.M2LogicRequestSpeedCmd_Pct   := M2LogicRequestSpeedCmd_Pct;
Data.KoboldContactorCmdArbitrated := KoboldContactorCmdArbitrated;
Data.WinchM1State                 := WinchM1State;
Data.WinchM2State                 := WinchM2State;
Data.WinchM1Safety                := WinchM1Safety;
Data.WinchM2Safety                := WinchM2Safety;
Data.SyncState                    := SyncState;
Data.WinchSyncError               := instWinchSync.Fault.Error;
Data.WinchSyncSignedDeltaPosM     := instWinchSync.SignedDeltaPosM;
Data.BucketState                  := BucketState;
Data.Benne_IsRoughlyClosed        := Benne_IsRoughlyClosed;
Data.BucketBusy                   := instBucket.Lifecycle.Busy;
Data.BucketDone                   := instBucket.Lifecycle.Done;
Data.BucketError                  := instBucket.Fault.Error;
Data.ArmingPermit                 := ArmingPermit;
// Usage effectif d'un override/bypass de position (consommé PRG_03 → FB_Modes)
Data.PositionLimitOverriddenM1    := PositionLimitOverriddenM1;
Data.PositionLimitOverriddenM2    := PositionLimitOverriddenM2;

{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS & REARMEMENT
ResetEdge(CLK := Reset);

IF ResetEdge.Q OR BypassGlobal THEN
    CfgFaultLatched       := FALSE;
    OffsetMaxFaultLatched := FALSE;
    TimeoutFaultLatched   := FALSE;
    M1SlipFaultLatched    := FALSE;
    HomingFaultLatched    := FALSE;
END_IF;

IF NOT BypassGlobal THEN
    // Cause 0 : Configuration géométrie benne
    IF (Config.OffsetOpenM >= Config.OffsetCloseM)
       OR (Config.OffsetOpenM < 0.0) THEN
        CfgFaultLatched := TRUE;
    END_IF;
    instCauses[0].Active   := CfgFaultLatched;
    instCauses[0].Latching := TRUE;
    instCauses[0].Texte    := 'Configuration geometrie benne invalide';

    // Cause 1 : Dépassement écart max
    MaxAllowedOffset := Config.OffsetCloseM + 2.0;
    IF (CablePosM2 > (CablePosM1 + MaxAllowedOffset)) OR (CablePosM2 < CablePosM1) THEN
        OffsetMaxFaultLatched := TRUE;
    END_IF;
    instCauses[1].Active   := OffsetMaxFaultLatched;
    instCauses[1].Latching := TRUE;
    instCauses[1].Texte    := 'Depassement ecart maximum autorise benne';

    // Cause 2 : Timeout
    TonTimeout(IN := Lifecycle.Busy, PT := CfgTimeoutDuration);
    IF TonTimeout.Q THEN
        TimeoutFaultLatched := TRUE;
    END_IF;
    instCauses[2].Active   := TimeoutFaultLatched;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Timeout commande deplacement benne';

    // Cause 3 : Glissement M1
    M1SlipDetected := Lifecycle.Busy AND (ABS(CablePosM1 - M1RefPosM) > M1SlipToleranceM);
    IF M1SlipDetected THEN
        M1SlipFaultLatched := TRUE;
    END_IF;
    instCauses[3].Active   := M1SlipFaultLatched;
    instCauses[3].Latching := TRUE;
    instCauses[3].Texte    := 'Glissement treuil M1 pendant manoeuvre benne';

    // Cause 4 : Non référencé
    IF NOT HomedM1 OR NOT HomedM2 THEN
        HomingFaultLatched := TRUE;
    END_IF;
    instCauses[4].Active   := HomingFaultLatched;
    instCauses[4].Latching := TRUE;
    instCauses[4].Texte    := 'Codeurs treuils non references pour sequence benne';
ELSE
    TonTimeout(IN := FALSE);
    M1SlipDetected := FALSE;
    instCauses[0].Active := FALSE;
    instCauses[1].Active := FALSE;
    instCauses[2].Active := FALSE;
    instCauses[3].Active := FALSE;
    instCauses[4].Active := FALSE;
END_IF;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate securite"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    IF Lifecycle.Busy OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    Ready := FALSE;
    ActiveOffsetValid := FALSE;
    ActiveOffsetM := 0.0;
    DeltaPosition_M := 0.0;
    RemainingTravelM := 0.0;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_BucketJogLimit := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Premier cycle & recalage boutons IHM"}
IF FirstCycle THEN
    FirstCycle := FALSE;
    IF NOT BucketState.IsOpen AND NOT BucketState.IsClosed THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
END_IF;

IF MachineHomingCommitOpen AND NOT Lifecycle.Busy THEN
    BucketState.IsOpen := TRUE;
    BucketState.IsClosed := FALSE;
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;

IF MachineHomingCommitClose AND NOT Lifecycle.Busy THEN
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := TRUE;
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;
{endregion}

{region "§4 Séquencement mouvement benne"}
SevereError := Fault.Error;

IF SevereError THEN
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_BucketJogLimit := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
ELSE
    // Prise en compte des demandes IHM — anti-traversée (TC-P10-025) :
    // demande benne refusée si un treuil agit (M1_Busy OR M2_Busy) à l'entrée READY.
    IF CmdOpen_IHM AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
        OpenReq := TRUE;
        CloseReq := FALSE;
    ELSIF CmdClose_IHM AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
        CloseReq := TRUE;
        OpenReq := FALSE;
    END_IF;

    BusyEdge(CLK := (CloseReq OR OpenReq) AND MotionRequestActive);

    IF BusyEdge.Q THEN
        M1RefPosM := CablePosM1;
        M2StartPosM := CablePosM2;
        WasOpenAtStart := BucketState.IsOpen;
        WasClosedAtStart := BucketState.IsClosed;
        LeftStartSinceArm := FALSE;
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;

    IF Lifecycle.Busy THEN
        IF CloseReq THEN
            RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
            M2_BucketJogLimit := TRUE;
            IF MotionRequestActive AND (MotionDirection = 1) THEN
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSIF MotionRequestActive AND (MotionDirection = -1) THEN
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSE
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSIF OpenReq THEN
            RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
            M2_BucketJogLimit := TRUE;
            IF MotionRequestActive AND (MotionDirection = -1) THEN
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSIF MotionRequestActive AND (MotionDirection = 1) THEN
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSE
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSE
            M2_StartStop := FALSE;
            M2_Direction := 0;
            M2_BucketJogLimit := FALSE;
        END_IF;

        IF (CloseReq AND (CablePosM2 > M2StartPosM)) OR (OpenReq AND (CablePosM2 < M2StartPosM)) THEN
            LeftStartSinceArm := TRUE;
        END_IF;

        // Arrêt fermeture
        IF CloseReq THEN
            IF CablePosM2 >= (CablePosM1 + Config.OffsetCloseM - Config.CloseAnticipationM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;
                BucketState.IsOpen := FALSE;
                BucketState.IsClosed := TRUE;
                BucketState.LastPosM2Close := CablePosM2;
                BucketState.StateIncoherent := FALSE;
                CloseReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            ELSIF LeftStartSinceArm AND (CablePosM2 <= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;
                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;
                CloseReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            END_IF;
        END_IF;

        // Arrêt ouverture
        IF OpenReq THEN
            IF CablePosM2 <= (CablePosM1 + Config.OffsetOpenM + Config.OpenAnticipationM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;
                BucketState.IsOpen := TRUE;
                BucketState.IsClosed := FALSE;
                BucketState.LastPosM2Open := CablePosM2;
                BucketState.StateIncoherent := FALSE;
                OpenReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            ELSIF LeftStartSinceArm AND (CablePosM2 >= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;
                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;
                OpenReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            END_IF;
        END_IF;
    ELSIF Lifecycle.Done THEN
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_BucketJogLimit := FALSE;
        RemainingTravelM := 0.0;
        IF NOT MotionRequestActive THEN
            Lifecycle.Done := FALSE;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§5 Offset actif et validite"}
DeltaPosition_M := CablePosM2 - CablePosM1;

IF Lifecycle.Busy THEN
    ActiveOffsetM := CablePosM2 - CablePosM1;
    HoldOffsetM := ActiveOffsetM;
ELSIF CloseReq OR BucketState.IsClosed THEN
    ActiveOffsetM := Config.OffsetCloseM;
    HoldOffsetM := ActiveOffsetM;
ELSIF OpenReq OR BucketState.IsOpen THEN
    ActiveOffsetM := Config.OffsetOpenM;
    HoldOffsetM := ActiveOffsetM;
ELSE
    ActiveOffsetM := HoldOffsetM;
END_IF;

ActiveOffsetValid := Enable AND PowerContactorEngaged
                     AND NOT BucketState.StateIncoherent
                     AND (Fault.ErrorId = 16#0000)
                     AND (MachineHomed OR (BucketState.IsOpen XOR BucketState.IsClosed))
                     AND NOT MachineHomingActive;
BucketState.ActiveOffsetValid := ActiveOffsetValid;
{endregion}

// === IMPLEMENTATION ===

Ready := Enable;

IF NOT Enable THEN
    CmdOpen_IHM  := FALSE;
    CmdClose_IHM := FALSE;
    KoboldContactorCmdArbitrated := FALSE;
    WinchBothDiveBucketOpenArmed    := FALSE;
    WinchBothAscentBucketCloseArmed := FALSE;
ELSE
    // ── Règle absolue en pilotage both normal (bit-identique PRG_04 §1) ──
    // Descente autorisée UNIQUEMENT benne ouverte, montée UNIQUEMENT benne fermée.
    WinchBothDiveBucketOpenArmed := Context.TglEnableCoupledBucketSequencing
        AND (Auth.Mode <> E_Mode.SEMI_AUTO)
        AND Context.MotionActive AND (Context.MotionDirection = -1)
        AND NOT Context.BucketIsOpen;
    WinchBothAscentBucketCloseArmed := Context.TglEnableCoupledBucketSequencing
        AND (Auth.Mode <> E_Mode.SEMI_AUTO)
        AND Context.MotionActive AND (Context.MotionDirection = 1)
        AND NOT Context.BucketIsClosed;

    // ── Ouverture benne : bouton IHM OU séquencement couplé descente benne ouverte
    //    OU demande cycle (bit-identique PRG_04 §2) ──
    CmdOpen_IHM := IHM.BtnOpen OR WinchBothDiveBucketOpenArmed OR ReqBucket.ReqOpen;

    // ── Fermeture benne : demande cycle > séquencement couplé montée benne fermée
    //    > bouton IHM (bit-identique PRG_04 §1) ──
    IF ReqBucket.ReqClose THEN
        CmdClose_IHM := TRUE;
    ELSIF WinchBothAscentBucketCloseArmed THEN
        CmdClose_IHM := TRUE;
    ELSE
        CmdClose_IHM := IHM.BtnClose;
    END_IF;

    // ── Contacteur Kobold : demande cycle (source unique PRG_03, bit-identique PRG_04 §1) ──
    KoboldContactorCmdArbitrated := ReqBucket.ReqKoboldMeasureEnable;
END_IF;

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS & REARMENT
ResetEdge(CLK := Reset);

IF ResetEdge.Q OR BypassGlobal THEN
    EncoderFaultLatched           := FALSE;
    MotorThermalFaultLatched      := FALSE;
    PhaseRotationFaultLatched     := FALSE;
    MecaAFaultLatched             := FALSE;
    MecaBFaultLatched             := FALSE;
    MecaCFaultLatched             := FALSE;
    BrakeThermalFaultLatched      := FALSE;
    MecaDFaultLatched             := FALSE;
    MecaEFaultLatched             := FALSE;
    MecaEEscaladeFaultLatched     := FALSE;
    OppositeDirectionFaultLatched := FALSE;
    NoMovementFaultLatched        := FALSE;
END_IF;

IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    EncoderFaultLatched           := FALSE;
    MotorThermalFaultLatched      := FALSE;
    PhaseRotationFaultLatched     := FALSE;
    MecaAFaultLatched             := FALSE;
    MecaBFaultLatched             := FALSE;
    MecaCFaultLatched             := FALSE;
    BrakeThermalFaultLatched      := FALSE;
    MecaDFaultLatched             := FALSE;
    MecaEFaultLatched             := FALSE;
    MecaEEscaladeFaultLatched     := FALSE;
    OppositeDirectionFaultLatched := FALSE;
    NoMovementFaultLatched        := FALSE;
END_IF;

IF NOT BypassGlobal THEN
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // Cause 0 : Perte com opérateur (live)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        instCauses[0].Active := (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk);
    ELSE
        instCauses[0].Active := FALSE;
    END_IF;
    instCauses[0].Latching := FALSE;
    instCauses[0].Texte    := 'Perte communication operateur treuil';

    // Cause 1 : Perte codeur (latched)
    IF NOT (BypassProcess OR EncoderFaultBypass) AND NOT EncoderAvailable THEN
        EncoderFaultLatched := TRUE;
    END_IF;
    instCauses[1].Active   := EncoderFaultLatched;
    instCauses[1].Latching := TRUE;
    instCauses[1].Texte    := 'Perte ou defaut codeur treuil';

    // Cause 2 : Surchauffe thermique moteur (latched)
    IF NOT (BypassSafety OR BypassMotorThermal) AND ThermalFeedback THEN
        MotorThermalFaultLatched := TRUE;
    END_IF;
    instCauses[2].Active   := MotorThermalFaultLatched;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Surchauffe thermique moteur treuil';

    // Cause 3 : Mou de câble (live / auto-effaçable)
    IF NOT BypassProcess AND SlackCableDetected THEN
        instCauses[3].Active := TRUE;
    ELSE
        instCauses[3].Active := FALSE;
    END_IF;
    instCauses[3].Latching := FALSE;
    instCauses[3].Texte    := 'Detection mou de cable treuil';

    // Cause 4 : Rotation phases (latched)
    IF NOT (BypassProcess OR BypassPhaseRotation) AND NOT PhaseRotationOk THEN
        PhaseRotationFaultLatched := TRUE;
    END_IF;
    instCauses[4].Active   := PhaseRotationFaultLatched;
    instCauses[4].Latching := TRUE;
    instCauses[4].Texte    := 'Defaut rotation de phases treuil';

    // Cause 5 : Fin de course haut capteur (live)
    IF NOT (BypassProcess OR BypassTopLimitSwitch) AND (NOT TopPositionSensor AND NOT InReferencingMode) THEN
        instCauses[5].Active := TRUE;
    ELSE
        instCauses[5].Active := FALSE;
    END_IF;
    instCauses[5].Latching := FALSE;
    instCauses[5].Texte    := 'Fin de course haut capteur atteint';

    // Cause 6 : Limite max câble descente (live)
    IF NOT (BypassProcess OR BypassCableLimitSwitch) AND ((CfgCableLimitDescentM < 0.0) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode) THEN
        instCauses[6].Active := TRUE;
    ELSE
        instCauses[6].Active := FALSE;
    END_IF;
    instCauses[6].Latching := FALSE;
    instCauses[6].Texte    := 'Limite basse cable atteinte';

    // Cause 7 : Méca A dérive à l'arrêt (latched)
    DriftGuardA(
        Arm        := NOT (BypassSafety OR BypassMecaA) AND FwdRevSpeedFeedbackOff AND NOT BrakeFeedback AND NOT BenneHoldStillActive,
        PositionM  := CablePosM,
        ToleranceM := UncommandedDriftToleranceM
    );
    MecaADriftM := DriftGuardA.DriftM;
    IF DriftGuardA.Violation THEN MecaAFaultLatched := TRUE; END_IF;
    instCauses[7].Active   := MecaAFaultLatched;
    instCauses[7].Latching := TRUE;
    instCauses[7].Texte    := 'Derive non commandee treuil (Meca A)';

    // Cause 8 : Méca B absence confirmation arrêt (latched)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        UncommandedActiveB := JoystickYNeutral AND NOT BenneHoldStillActive AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback);
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN MecaBFaultLatched := TRUE; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    MecaBElapsedTime := TonMecaB.ET;
    instCauses[8].Active   := MecaBFaultLatched;
    instCauses[8].Latching := TRUE;
    instCauses[8].Texte    := 'Absence confirmation arret contacteurs/frein (Meca B)';

    // Cause 9 : Méca C glissement benne (latched)
    DriftGuardC(
        Arm        := NOT (BypassSafety OR BypassMecaC) AND BenneHoldStillActive,
        PositionM  := CablePosM,
        ToleranceM := BenneSlipToleranceM
    );
    MecaCDriftM := DriftGuardC.DriftM;
    IF DriftGuardC.Violation THEN MecaCFaultLatched := TRUE; END_IF;
    instCauses[9].Active   := MecaCFaultLatched;
    instCauses[9].Latching := TRUE;
    instCauses[9].Texte    := 'Glissement treuil pendant cycle benne (Meca C)';

    // Cause 10 : Surchauffe thermique frein (latched)
    IF NOT (BypassSafety OR BypassBrakeThermal) AND BrakeThermalFeedback THEN
        BrakeThermalFaultLatched := TRUE;
    END_IF;
    instCauses[10].Active   := BrakeThermalFaultLatched;
    instCauses[10].Latching := TRUE;
    instCauses[10].Texte    := 'Surchauffe thermique frein treuil';

    // Cause 11 : Méca D escalade capteur haut (latched)
    IF NOT (BypassSafety OR BypassMecaD) THEN
        UncommandedActiveD := NOT TopPositionSensor AND NOT InReferencingMode AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback);
        TonMecaD(IN := UncommandedActiveD, PT := PostRampTimeout);
        IF TonMecaD.Q THEN MecaDFaultLatched := TRUE; END_IF;
    ELSE
        TonMecaD(IN := FALSE);
    END_IF;
    instCauses[11].Active   := MecaDFaultLatched;
    instCauses[11].Latching := TRUE;
    instCauses[11].Texte    := 'Escalade fin de course haut (Meca D)';

    // Cause 12 & 13 : Méca E écart critique synchro & escalade (latched)
    IF NOT (BypassProcess OR BypassMecaE) AND SyncEnable AND NOT BenneBusy AND NOT InReferencingMode AND NOT OtherWinchInhibited
       AND (ABS(CablePosM - ExpectedOtherWinchPosM) > CriticalSyncToleranceM) THEN
        MecaEFaultLatched := TRUE;
    END_IF;
    instCauses[12].Active   := MecaEFaultLatched;
    instCauses[12].Latching := TRUE;
    instCauses[12].Texte    := 'Ecart critique synchronisation treuil (Meca E)';

    TonMecaE(
        IN := NOT (BypassSafety OR BypassMecaE) AND MecaEFaultLatched AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback),
        PT := PostRampTimeout
    );
    IF TonMecaE.Q THEN MecaEEscaladeFaultLatched := TRUE; END_IF;
    instCauses[13].Active   := MecaEEscaladeFaultLatched;
    instCauses[13].Latching := TRUE;
    instCauses[13].Texte    := 'Escalade ecart synchronisation (Meca E)';

    // Cause 14 : Sens opposé (latched)
    OppositeDirectionActive := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
        AND (((Direction > 0) AND (MeasuredSpeedSignedMps < -MovementSpeedThresholdMps))
          OR ((Direction < 0) AND (MeasuredSpeedSignedMps > MovementSpeedThresholdMps))));
    TonOppositeDirection(IN := OppositeDirectionActive, PT := OppositeDirectionTimeout);
    IF TonOppositeDirection.Q THEN OppositeDirectionFaultLatched := TRUE; END_IF;
    instCauses[14].Active   := OppositeDirectionFaultLatched;
    instCauses[14].Latching := TRUE;
    instCauses[14].Texte    := 'Sens reel oppose a la commande treuil';

    // Cause 15 : Absence mouvement (latched)
    TonNoMovement(
        IN := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
              AND (ABS(MeasuredSpeedSignedMps) < MovementSpeedThresholdMps)),
        PT := NoMovementTimeout
    );
    IF TonNoMovement.Q THEN NoMovementFaultLatched := TRUE; END_IF;
    instCauses[15].Active   := NoMovementFaultLatched;
    instCauses[15].Latching := TRUE;
    instCauses[15].Texte    := 'Absence mouvement malgre commande treuil';

ELSE
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
END_IF;

// ContactorStuck : proprietaire UNIQUE de la detection contacteur colle.
// Escalade : Meca B (bit8) -> SafeStop + PowerCutOff apres PostRampTimeout si le
// collage persiste. Le champ ContactorsCheck.StuckClosed de FB_Winch est force a
// FALSE (Phase 0) ; la re-alimentation IHM/Troubleshooting se fera depuis cette sortie.
ContactorStuck := MecaBFaultLatched;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SafeStop := FALSE;
    DescendPermit := FALSE;
    AscentPermit := FALSE;
    PowerCutOff := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    MecaBElapsedTime := T#0s;
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Arbitrage sorties securite"}
// 📤 3. ARBITRAGE SÉCURITÉ
IF NOT PowerContactorEngaged THEN
    SafeStop := TRUE;
ELSIF NOT SyncEnable THEN
    SafeStop := (Fault.ErrorId AND 16#FF97) <> 16#0000;
ELSE
    SafeStop := (Fault.ErrorId AND 16#FF9F) <> 16#0000;
END_IF;

DescendPermit := NOT (
    (((Fault.ErrorId AND 16#0040) <> 16#0000 OR NOT PowerContactorEngaged) AND NOT (BypassGlobal OR BypassCableLimitSwitch))
    OR (((CfgCableLimitDescentM < 0.0) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode) AND NOT BypassCableLimitSwitch)
    OR (LimitLegalReached AND NOT (BypassProcess OR BypassLimitLegal))
    OR (((Fault.ErrorId AND 16#0008) <> 16#0000 AND NOT SyncEnable) AND NOT (BypassProcess OR BypassGlobal))
);

AscentPermit := NOT (
    (((Fault.ErrorId AND 16#0020) <> 16#0000
    OR (NOT TopPositionSensor AND NOT InReferencingMode))
    AND NOT BypassTopLimitSwitch)
    // TopLimitM porte deja la relaxation 7,5->8,5 m (override N1 / bypass N2, bornee par la
    // bande de ralentissement, PRG_04 TopLimitM1_M/TopLimitM2_M) : la butee logicielle reste
    // active a la valeur relevee. Bypasser le logiciel releve la butee, il ne la supprime pas.
    OR (Homed AND NOT HomingSuspect AND NOT InReferencingMode AND (CablePosM >= TopLimitM))
);

PowerCutOff := (Fault.ErrorId AND 16#2F84) <> 16#0000;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS & REARMEMENT
ResetEdge(CLK := Reset);
EnableRisingEdge(CLK := Enable);

IF ResetEdge.Q OR BypassGlobal THEN
    SpeedStepConfigFaultLatched := FALSE;
    ContactorsCheck.StuckClosed := FALSE;
END_IF;

IF Enable AND SpeedStep.ConfigError THEN
    SpeedStepConfigFaultLatched := TRUE;
END_IF;

// FB_Safety_Winch est l'unique proprietaire de la detection contacteur colle.
// FB_Winch conserve le champ public pour compatibilite IHM/Troubleshooting,
// mais ne produit plus ce defaut.
instCauses[1].Active   := FALSE;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Contacteur colle gere par FB_Safety_Winch (T181-08)';

instCauses[2].Active   := SpeedStepConfigFaultLatched;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Configuration table des paliers vitesse invalide';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SpeedStep(Enable := FALSE, SpeedStepReq := 0, Table := Config.SpeedStepTable);
    DirectionInterlock(Enable := FALSE, EnableRising := FALSE, Reset := Reset, ReqDirection := 0,
                       ChangeDelayUp := Config.DirectionInterlockDelayUp,
                       ChangeDelayDown := Config.DirectionInterlockDelayDown);
    StepShaper(Enable := FALSE, TargetStep := 0, StepRampDelay := Config.StepRampDelayAscent);
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    RequestedStep := 0;
    StepNumber := StepShaper.ShapedStep;
    CommandedDirection := DirectionInterlock.CommandedDirection;
    DirectionChangePending := DirectionInterlock.DirectionChangePending;
    TonContactorsDropped(IN := FALSE);
    ContactorsCheck.Command := FALSE;
    ContactorsCheck.Feedback := NOT Sensors.ContactorsAllOff;
    InTopSlowdownZone := FALSE;
    InBottomSlowdownZone := FALSE;
    // §3bis : coupure dure -> aucun maintien de sens possible, etat interne purge.
    SenseHoldRequest := FALSE;
    SenseHoldActiveInt := FALSE;
    SenseHoldTimer(IN := FALSE, PT := T#900ms);
    PrevStepNumber := 0;
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Permis et zones de ralentissement"}
EffectiveSafeStop := SafeStop OR (DriveRequest.Direction > 0 AND NOT AscentPermit) OR (DriveRequest.Direction < 0 AND NOT DescendPermit);

InTopSlowdownZone := Sensors.Homed AND NOT Sensors.HomingSuspect AND (Sensors.CablePosM >= (DriveRequest.TopLimitM - Config.SlowdownDistance_M));
InBottomSlowdownZone := Sensors.Homed AND NOT Sensors.HomingSuspect AND (Sensors.CablePosM <= (DriveRequest.BottomLimitM + Config.SlowdownDistance_M));

IF DriveRequest.Direction > 0 THEN
    ActiveMaxStep := DriveRequest.MaxStepUp;
    IF InTopSlowdownZone THEN
        ActiveMaxStep := MIN(ActiveMaxStep, Config.SlowdownMaxStep);
    END_IF;
ELSIF DriveRequest.Direction < 0 THEN
    ActiveMaxStep := DriveRequest.MaxStepDown;
    IF InBottomSlowdownZone THEN
        ActiveMaxStep := MIN(ActiveMaxStep, Config.SlowdownMaxStep);
    END_IF;
ELSE
    ActiveMaxStep := DriveRequest.MaxStepUp;
END_IF;

IF DriveRequest.HomingApproachActive THEN
    ActiveMaxStep := 1;
END_IF;
{endregion}

{region "§4 Interlock direction"}
// 🔀 4. INTERLOCK DIRECTION (extrait dans FB_WinchDirectionInterlock, D18)
DirectionInterlock(
    Enable := (StepNumber = 0) AND Sensors.ContactorsAllOff,
    EnableRising := EnableRisingEdge.Q,
    Reset := Reset,
    ReqDirection := DriveRequest.Direction,
    ChangeDelayUp := Config.DirectionInterlockDelayUp,
    ChangeDelayDown := Config.DirectionInterlockDelayDown
);
CommandedDirection := DirectionInterlock.CommandedDirection;
DirectionChangePending := DirectionInterlock.DirectionChangePending;
DirectionChangeDelayElapsed := DirectionInterlock.DelayElapsed;
{endregion}

{region "§5 Paliers vitesse et contacteurs"}
IF DirectionChangePending OR (DriveRequest.Direction = 0) OR EffectiveSafeStop OR NOT DriveRequest.StartStop THEN
    RampTargetPct := 0.0;
ELSE
    RampTargetPct := LIMIT(0.0, DriveRequest.SpeedTgt_Pct, 100.0);
END_IF;

// Décodage consigne % -> palier conservé ici, immédiatement en amont du
// décodeur contacteurs. FB_SpeedStep ne reçoit plus que le palier discret.
SpeedStepHyst1(IN := REAL_TO_INT(RampTargetPct), HIGH := REAL_TO_INT(Config.SpeedStepTable.StepThreshold_Pct[1] + Config.SpeedStepHystMargin), LOW := REAL_TO_INT(Config.SpeedStepTable.StepThreshold_Pct[1] - Config.SpeedStepHystMargin));
SpeedStepHyst2(IN := REAL_TO_INT(RampTargetPct), HIGH := REAL_TO_INT(Config.SpeedStepTable.StepThreshold_Pct[2] + Config.SpeedStepHystMargin), LOW := REAL_TO_INT(Config.SpeedStepTable.StepThreshold_Pct[2] - Config.SpeedStepHystMargin));
SpeedStepHyst3(IN := REAL_TO_INT(RampTargetPct), HIGH := REAL_TO_INT(Config.SpeedStepTable.StepThreshold_Pct[3] + Config.SpeedStepHystMargin), LOW := REAL_TO_INT(Config.SpeedStepTable.StepThreshold_Pct[3] - Config.SpeedStepHystMargin));
SpeedStepHyst4(IN := REAL_TO_INT(RampTargetPct), HIGH := REAL_TO_INT(Config.SpeedStepTable.StepThreshold_Pct[4] + Config.SpeedStepHystMargin), LOW := REAL_TO_INT(Config.SpeedStepTable.StepThreshold_Pct[4] - Config.SpeedStepHystMargin));

IF RampTargetPct <= 0.1 THEN
    RampTargetStep := 0;
ELSE
    RampTargetStep := 1;
    IF NOT SpeedStepHyst1.OUT THEN RampTargetStep := 2; END_IF;
    IF NOT SpeedStepHyst2.OUT THEN RampTargetStep := 3; END_IF;
    IF NOT SpeedStepHyst3.OUT THEN RampTargetStep := 4; END_IF;
    IF NOT SpeedStepHyst4.OUT THEN RampTargetStep := 5; END_IF;
END_IF;

SpeedStep(
    Enable := (RampTargetPct > 0.1),
    SpeedStepReq := RampTargetStep,
    Table := Config.SpeedStepTable,
    MaxStepNumber := ActiveMaxStep
);
RequestedStep := SpeedStep.StepNumber;

// 🛡️ Garde-fou vitesse : bride le palier demande si la vitesse n'est pas stable
// (SpeedGuardReady=FALSE -> palier 1) ou si la bande mesuree est inferieure au
// palier demande (pas de passage aux paliers superieurs sans vitesse confirmee).
SpeedGuardLimited := FALSE;
IF Sensors.SpeedGuardEnable THEN
    IF NOT Sensors.SpeedGuardReady THEN
        IF RequestedStep > 1 THEN
            RequestedStep := 1;
            SpeedGuardLimited := TRUE;
        END_IF;
    ELSIF (Sensors.MeasuredSpeedBand >= 1) AND (Sensors.MeasuredSpeedBand <= 5) AND (RequestedStep > Sensors.MeasuredSpeedBand) THEN
        RequestedStep := Sensors.MeasuredSpeedBand;
        SpeedGuardLimited := TRUE;
    END_IF;
END_IF;

// 🤿 Plancher palier descente -- plongee Kobold.
// Injecte MinStepDown sur la CIBLE (RequestedStep, consommee par le shaper ci-dessous),
// JAMAIS sur StepNumber directement. Actif uniquement en descente commandee
// (StartStop AND Direction=-1) : relache joystick (StartStop=FALSE) -> aucun plancher,
// l'arret franc RequestedStep=0 / RampTargetPct=0 est preserve.
// Regle d'agregation : le PLAFOND GAGNE -- si le plancher depasse le plafond courant
// ActiveMaxStep (ex. SlowdownMaxStep -> palier 1 en bordure basse), on borne au plafond.
IF DriveRequest.StartStop AND (DriveRequest.Direction = -1) AND (DriveRequest.MinStepDown > 0) THEN
    IF RequestedStep < DriveRequest.MinStepDown THEN
        RequestedStep := DriveRequest.MinStepDown;
    END_IF;
    IF RequestedStep > ActiveMaxStep THEN
        RequestedStep := ActiveMaxStep;
    END_IF;
END_IF;

// ⚙️ Cadencement de palier (extrait dans FB_WinchStepShaper, D10).
// Les deux cadences historiques sont preservees sans reutiliser les delais
// d'interlock direction : 1 s en montee, 500 ms en descente.
IF CommandedDirection = -1 THEN
    EffectiveStepRampDelay := Config.StepRampDelayDescending;
ELSE
    EffectiveStepRampDelay := Config.StepRampDelayAscent;
END_IF;
StepShaper(
    Enable := Enable,
    TargetStep := RequestedStep,
    StepRampDelay := EffectiveStepRampDelay
);
StepNumber := StepShaper.ShapedStep;
BusinessStepDelayElapsed := StepShaper.StepDelayElapsed;

IF StepNumber > 0 AND CommandedDirection = 1 THEN
    RelayFwd := TRUE;
    RelayRev := FALSE;
ELSIF StepNumber > 0 AND CommandedDirection = -1 THEN
    RelayFwd := FALSE;
    RelayRev := TRUE;
ELSE
    RelayFwd := FALSE;
    RelayRev := FALSE;
END_IF;

Contactor1 := (StepNumber = 1);
Contactor2 := (StepNumber = 2);
Contactor3 := (StepNumber = 3);
Contactor4 := (StepNumber = 4);

AllContactorsCommandedOff := (NOT RelayFwd) AND (NOT RelayRev)
                             AND (NOT Contactor1) AND (NOT Contactor2) AND (NOT Contactor3) AND (NOT Contactor4);

ContactorsCheck.Command  := NOT AllContactorsCommandedOff;
ContactorsCheck.Feedback := NOT Sensors.ContactorsAllOff;
TonContactorsDropped(IN := FALSE, PT := Config.ContactorFeedbackTimeout);
ContactorsCheck.StuckClosed := FALSE; // force a FALSE (Phase 0) : detection contacteur colle produite par FB_Safety_Winch, re-alimentee a la phase suivante
ContactorsCheck.StuckOpen := FALSE;

IF Fault.Error THEN
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_IF;
{endregion}

{region "§5bis Intention de maintien du contacteur de sens (§3bis / T181-01)"}
// Quand le palier temporise StepNumber vient de retomber a 0 alors qu'un sens etait
// commande, FB_Winch DEMANDE a la barriere finale (FB_WinchOutputInterlock) de TENIR
// le contacteur de sens le temps que le moteur ralentisse (inertie). Borne par
// T_hold_internal (garde interne, < MaxSenseHoldTime de la barriere = T#1s).
// Coupures dures -> retombee immediate, jamais de maintien (SafeStop / defaut / perte
// puissance / NOT Enable geree a la gate §2).
SenseHoldHardCut := (NOT PowerContactorEngaged) OR EffectiveSafeStop OR Fault.Error;

IF SenseHoldHardCut THEN
    SenseHoldActiveInt := FALSE;
ELSIF (PrevStepNumber > 0) AND (StepNumber = 0) AND (CommandedDirection <> 0) THEN
    SenseHoldActiveInt := TRUE;   // front de chute de palier a 0 avec sens encore actif
END_IF;

// T_hold_internal PROVISOIRE essai site (base physique : inertie moteur + chute de couple) ;
// tenu < MaxSenseHoldTime de FB_WinchOutputInterlock pour que la barriere garde le dernier mot.
SenseHoldTimer(IN := SenseHoldActiveInt, PT := T#900ms);
IF SenseHoldTimer.Q OR (StepNumber > 0) THEN
    SenseHoldActiveInt := FALSE;  // borne de temps atteinte, ou nouveau mouvement demande
END_IF;

SenseHoldRequest := SenseHoldActiveInt AND NOT SenseHoldHardCut;
PrevStepNumber := StepNumber;
{endregion}

// === IMPLEMENTATION ===

Ready := Enable;

// Front de fin d'action benne (détecté en interne, mécanisme de sécurité)
BenneBusyFallEdge(CLK := Context.BucketBusy);

IF NOT Enable THEN
    StartStop := FALSE;
    Direction := 0;
    SpeedPct  := 0.0;
ELSE
    // ── Pont SEMI_AUTO : consomme la demande du séquenceur de cycle ──
    IF Auth.Mode = E_Mode.SEMI_AUTO THEN
        StartStop := ReqWinch.ReqStartStop;
        Direction := ReqWinch.ReqDirection;
        SpeedPct  := ReqWinch.SpeedTgtPct;
    ELSE
        // ── Mode manuel : commande both issue de l'intention UNIQUE PRG_03 (BothIntent),
        //    commande unitaire M1 dérivée des boutons/joystick (Select=1). ──
        IF NOT TglJoystickMaster THEN
            // Mode Boutons IHM
            IF BothIntent.Active THEN
                // Both (BtnWinchBothUp/Down) — source unique PRG_03, plus de re-dérivation
                Direction := BothIntent.Direction;
                SpeedPct  := 100.0;
            ELSIF IHM.BtnUpM1 THEN
                Direction := 1;
                SpeedPct  := 100.0;
            ELSIF IHM.BtnDownM1 THEN
                Direction := -1;
                SpeedPct  := 100.0;
            ELSE
                Direction := 0;
                SpeedPct  := 0.0;
            END_IF;
        ELSE
            // Mode Joystick Maître — M1 unitaire si Select = 1, both si Select = 0
            IF Auth.JoystickWinchSelectArbitrated = 1 THEN
                Direction := Joystick.AxisY.Direction;
                SpeedPct  := ABS(Joystick.AxisY.SpeedTgt);
            ELSIF BothIntent.Active THEN
                // Both (Select=0) — source unique PRG_03, plus de re-dérivation
                Direction := BothIntent.Direction;
                SpeedPct  := ABS(Joystick.AxisY.SpeedTgt);
            ELSE
                Direction := 0;
                SpeedPct  := 0.0;
            END_IF;
        END_IF;

        // Gating StartStop (bit-identique PRG_04 §3) — homme-mort qualifié en joystick
        StartStop := (Direction <> 0)
                  AND NOT Context.BucketBusy
                  AND NOT Context.WinchBothMotionBlockedByBucket
                  AND NOT ((Context.SyncBlocksUp   AND (Direction = 1))
                        OR (Context.SyncBlocksDown AND (Direction = -1)))
                  AND (NOT TglJoystickMaster OR Joystick.DeadmanArmed);
    END_IF;

    // Front de fin d'action benne : arrêt forcé sauf mouvement both actif
    IF BenneBusyFallEdge.Q AND NOT (BothIntent.Active AND (BothIntent.Direction <> 0)) THEN
        StartStop := FALSE;
    END_IF;
END_IF;

// === IMPLEMENTATION ===

Ready := Enable;

// Front de fin d'action benne (détecté en interne, mécanisme de sécurité)
BenneBusyFallEdge(CLK := Context.BucketBusy);

IF NOT Enable THEN
    StartStop := FALSE;
    Direction := 0;
    SpeedPct  := 0.0;
ELSE
    // ── Chemin benne : M2 piloté par l'action benne (override) ──
    IF Context.BucketBusy AND Context.BucketM2StartStop THEN
        StartStop := Context.BucketM2StartStop;
        Direction := SEL(Context.BucketM2Open, -1, 1);  // Open → +1, Close → -1
        SpeedPct  := Cfg.BucketOverrideSpeedPct;
    ELSE
        // ── Pont SEMI_AUTO : consomme la demande du séquenceur de cycle ──
        IF Auth.Mode = E_Mode.SEMI_AUTO THEN
            StartStop := ReqWinch.ReqStartStop;
            Direction := ReqWinch.ReqDirection;
            SpeedPct  := ReqWinch.SpeedTgtPct;
        ELSE
            // ── Mode manuel : commande both issue de l'intention UNIQUE PRG_03 (BothIntent),
            //    commande unitaire M2 dérivée des boutons/joystick (Select=2). ──
            IF NOT TglJoystickMaster THEN
                // Mode Boutons IHM
                IF BothIntent.Active THEN
                    // Both (BtnWinchBothUp/Down) — source unique PRG_03, plus de re-dérivation
                    Direction := BothIntent.Direction;
                    SpeedPct  := 100.0;
                ELSIF IHM.BtnUpM2 THEN
                    Direction := 1;
                    SpeedPct  := 100.0;
                ELSIF IHM.BtnDownM2 THEN
                    Direction := -1;
                    SpeedPct  := 100.0;
                ELSE
                    Direction := 0;
                    SpeedPct  := 0.0;
                END_IF;
            ELSE
                // Mode Joystick Maître — M2 unitaire si Select = 2, both si Select = 0
                IF Auth.JoystickWinchSelectArbitrated = 2 THEN
                    Direction := Joystick.AxisY.Direction;
                    SpeedPct  := ABS(Joystick.AxisY.SpeedTgt);
                ELSIF BothIntent.Active THEN
                    // Both (Select=0) — source unique PRG_03, plus de re-dérivation
                    Direction := BothIntent.Direction;
                    SpeedPct  := ABS(Joystick.AxisY.SpeedTgt);
                ELSE
                    Direction := 0;
                    SpeedPct  := 0.0;
                END_IF;
            END_IF;

            // Gating StartStop (bit-identique PRG_04 §3) — synchro INVERSÉE vs M1,
            // homme-mort qualifié en joystick
            StartStop := (Direction <> 0)
                      AND NOT Context.WinchBothMotionBlockedByBucket
                      AND NOT ((Context.SyncBlocksUp   AND (Direction = -1))
                            OR (Context.SyncBlocksDown AND (Direction = 1)))
                      AND (NOT TglJoystickMaster OR Joystick.DeadmanArmed);
        END_IF;
    END_IF;

    // Front de fin d'action benne : arrêt forcé sauf mouvement both actif
    IF BenneBusyFallEdge.Q AND NOT (BothIntent.Active AND (BothIntent.Direction <> 0)) THEN
        StartStop := FALSE;
    END_IF;
END_IF;

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);

IF ResetEdge.Q AND (MeasuredSpeedMps >= 0.0) THEN
    ConfigOrSpeedFault := FALSE;
END_IF;

instCauses[0].Active   := ConfigOrSpeedFault;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Parametrage ou vitesse estimation charge invalide';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    SpeedBand := 0;
    EstimatedLoadPct := 0.0;
    Configured := FALSE;
    Ascending := FALSE;
    HasPreviousBand := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
Configured := LoadTable.IsConfigured;
Ascending := (MeasuredSpeedSignedMps > 0.0);
{endregion}

{region "§3 Classement vitesse"}
// 📏 3. CLASSEMENT DE LA VITESSE — hystérésis autour des 4 frontières.
IF (MeasuredSpeedMps < 0.0) OR (SpeedConfig.MaxMeasuredSpeedMps <= 0.0) THEN
    ConfigOrSpeedFault := TRUE;
    SpeedBand := 0;
ELSIF NOT HasPreviousBand THEN
    IF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[1] THEN
        PreviousSpeedBand := 1;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[2] THEN
        PreviousSpeedBand := 2;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[3] THEN
        PreviousSpeedBand := 3;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[4] THEN
        PreviousSpeedBand := 4;
    ELSE
        PreviousSpeedBand := 5;
    END_IF;
    HasPreviousBand := TRUE;
    SpeedBand := PreviousSpeedBand;
ELSE
    IF PreviousSpeedBand < 1 OR PreviousSpeedBand > 5 THEN
        PreviousSpeedBand := 1;
        ConfigOrSpeedFault := TRUE;
    END_IF;

    IF PreviousSpeedBand < 5 THEN
        IF MeasuredSpeedMps > (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand]
                               + SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand + 1;
        END_IF;
    END_IF;
    IF PreviousSpeedBand > 1 THEN
        IF MeasuredSpeedMps < (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand - 1]
                               - SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand - 1;
        END_IF;
    END_IF;
    SpeedBand := PreviousSpeedBand;
END_IF;
{endregion}

{region "§4 Lecture table"}
// 📊 4. LECTURE TABLE
EstimatedLoadPct := 0.0;
IF Configured THEN
    IF Ascending THEN
        IF ActiveSpeedStep >= 1 THEN
            IF ActiveSpeedStep <= 5 THEN
                IF SpeedBand >= 1 THEN
                    IF SpeedBand <= 5 THEN
                        SelectedLoadPct := LoadTable.LoadPctByStepAndSpeedBand[ActiveSpeedStep][SpeedBand];
                        IF (SelectedLoadPct < 0.0) OR (SelectedLoadPct > 100.0) THEN
                            ConfigOrSpeedFault := TRUE;
                        ELSE
                            EstimatedLoadPct := SelectedLoadPct;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    Ready := FALSE;
    DeltaPosM := 0.0; SignedDeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE; SyncDeviationWarn := FALSE; SyncDeviationFault := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Activation synchro"}
// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9)
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // Polarité positive (TRUE = synchro active)
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : actif par prudence
END_CASE;
{endregion}

{region "§3 Sous-blocs deviation et contacteurs"}
// 📏 4. ÉCART CODEURS (FB_SyncDeviation) + COHERENCE CONTACTEURS (FB_SyncContactor)
instDeviation(
    Enable               := Enable,
    Reset                := Reset,
    SyncEnable           := SyncActive,
    CablePosM1           := CablePosM1,
    CablePosM2           := CablePosM2,
    HomedAndReliableM1   := HomedAndReliableM1,
    HomedAndReliableM2   := HomedAndReliableM2,
    CfgSyncToleranceM    := CfgSyncToleranceM,
    CfgSyncCriticalToleranceM := CfgSyncCriticalToleranceM,
    ActiveOffsetM        := ActiveOffsetM,
    BypassGlobal         := BypassGlobal
);
DeltaPosM := instDeviation.DeltaPosM;
SignedDeltaPosM := instDeviation.SignedDeltaPosM;
SyncDeviationWarn := instDeviation.SyncDeviationWarn;
SyncDeviationFault := instDeviation.SyncDeviationFault;

instContactor(
    Enable          := Enable,
    Reset           := Reset,
    SyncEnable      := SyncActive,
    RelayFwdM1      := RelayFwdM1,
    RelayFwdM2      := RelayFwdM2,
    RelayRevM1      := RelayRevM1,
    RelayRevM2      := RelayRevM2,
    Contactor1_M1   := Contactor1_M1,
    Contactor1_M2   := Contactor1_M2,
    Contactor2_M1   := Contactor2_M1,
    Contactor2_M2   := Contactor2_M2,
    Contactor3_M1   := Contactor3_M1,
    Contactor3_M2   := Contactor3_M2,
    Contactor4_M1   := Contactor4_M1,
    Contactor4_M2   := Contactor4_M2,
    BypassGlobal    := BypassGlobal
);
{endregion}

{region "§4 Causes & Socle Défaut"}
IF NOT BypassGlobal THEN
    instCauses[0].Active   := instDeviation.SyncDeviationWarn;
    instCauses[0].Latching := FALSE;
    instCauses[0].Texte    := 'Alerte ecart synchronisation M1/M2';

    instCauses[1].Active   := instContactor.ContactorMismatch;
    instCauses[1].Latching := TRUE;
    instCauses[1].Texte    := 'Discordance contacteurs treuils M1/M2';

    instCauses[2].Active   := instDeviation.SyncDeviationFault;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Ecart critique synchronisation treuils M1/M2';
ELSE
    instCauses[0].Active := FALSE;
    instCauses[1].Active := FALSE;
    instCauses[2].Active := FALSE;
END_IF;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

SyncWarn := Fault.Error;
Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_DriftGuard) ===

IF Arm THEN
    IF NOT WasArmed THEN
        RefPosM := PositionM;   // Capture au 1er cycle armé uniquement
        WasArmed := TRUE;
    END_IF;
    DriftM := ABS(PositionM - RefPosM);
    Violation := DriftM > ToleranceM;
ELSE
    WasArmed := FALSE;
    DriftM := 0.0;
    Violation := FALSE;
END_IF;

{region "§0 Bornes et validation table"}
// Le plafond est borné avant le plancher : si le plancher demandé dépasse le
// plafond de sécurité, celui-ci garde la priorité.
_MaxStepClamped := LIMIT(1, MaxStepNumber, 5);
_MinStepClamped := LIMIT(1, MinStepNumber, _MaxStepClamped);

// Les seuils restent validés pour conserver le diagnostic table historique.
// Ils ne participent plus au calcul du palier dans ce FB.
_ConfigValid := TRUE;
_ConfigErrorIdInt := 16#0000;
IF NOT (Table.StepThreshold_Pct[1] < Table.StepThreshold_Pct[2] AND
        Table.StepThreshold_Pct[2] < Table.StepThreshold_Pct[3] AND
        Table.StepThreshold_Pct[3] < Table.StepThreshold_Pct[4] AND
        Table.StepThreshold_Pct[4] < Table.StepThreshold_Pct[5]) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;
IF (Table.StepThreshold_Pct[1] < 0.0) OR (Table.StepThreshold_Pct[5] > 100.0) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;
ConfigErrorId := _ConfigErrorIdInt;
ConfigError := (ConfigErrorId <> 16#0000);
{endregion}

{region "§1 Gate"}
// Relâche ou table invalide : aucun plancher ne peut maintenir un contacteur.
IF (NOT Enable) OR (NOT _ConfigValid) OR (SpeedStepReq <= 0) THEN
    StepNumber := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Clamp et table contacteurs"}
// Le plancher agit sur la cible. StepNumber ne reçoit jamais directement
// MinStepNumber ; LIMIT final garantit la plage 1..5 après le plafond.
StepNumber := LIMIT(_MinStepClamped, SpeedStepReq, _MaxStepClamped);

CASE StepNumber OF
    1:  Contactor1 := Table.P1R1; Contactor2 := Table.P1R2; Contactor3 := Table.P1R3; Contactor4 := Table.P1R4;
    2:  Contactor1 := Table.P2R1; Contactor2 := Table.P2R2; Contactor3 := Table.P2R3; Contactor4 := Table.P2R4;
    3:  Contactor1 := Table.P3R1; Contactor2 := Table.P3R2; Contactor3 := Table.P3R3; Contactor4 := Table.P3R4;
    4:  Contactor1 := Table.P4R1; Contactor2 := Table.P4R2; Contactor3 := Table.P4R3; Contactor4 := Table.P4R4;
    5:  Contactor1 := Table.P5R1; Contactor2 := Table.P5R2; Contactor3 := Table.P5R3; Contactor4 := Table.P5R4;
ELSE
    // Défense en profondeur face à une divergence type/outil.
    StepNumber := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_CASE;
{endregion}

// === IMPLEMENTATION ===

// Front Reset : purge la memoire de direction (un acquittement conscient reinitialise
// l'historique, une reprise apres Reset est un depart propre, pas une inversion).
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    LastDirection := 0;
    CommandedDirection := 0;
    DeadTimeArmed := FALSE;
    DirectionChangePending := FALSE;
END_IF;

// Delai effectif selon le sens demande
IF ReqDirection > 0 THEN
    EffectiveDelay := ChangeDelayUp;
ELSE
    EffectiveDelay := ChangeDelayDown;
END_IF;

// D18 : au front montant Enable avec sens maintenu, armer le temps mort
// (ne pas re-adopter le sens immediatement — pas de redemarrage inrush).
IF EnableRising AND (ReqDirection <> 0) THEN
    DeadTimeArmed := TRUE;
END_IF;

// Temporisation : compte quand un changement de sens est demande et treuil arrete
DirectionChangeDelay(
    IN := Enable AND (ReqDirection <> 0) AND (ReqDirection <> CommandedDirection),
    PT := EffectiveDelay
);
DelayElapsed := DirectionChangeDelay.ET;

// Adoption du sens
IF ReqDirection = 0 THEN
    // Neutre : CommandedDirection := 0 (relais/diagnostic neutres). La memoire du
    // dernier sens non nul (LastDirection) est conservee pour l'interlock de reprise.
    CommandedDirection := 0;
    DirectionChangePending := FALSE;
    DeadTimeArmed := FALSE;
ELSIF DeadTimeArmed THEN
    // D18 : temps mort au front Enable — pas d'adoption immediate
    DirectionChangePending := TRUE;
ELSIF DirectionChangeDelay.Q THEN
    // Temps mort ecoule : adoption du sens
    CommandedDirection := ReqDirection;
    DirectionChangePending := FALSE;
    DeadTimeArmed := FALSE;
ELSIF (CommandedDirection = 0) AND (ReqDirection <> 0) THEN
    // Depuis le neutre : depart immediat si reprise du MEME sens (ou premier sens),
    // sinon (sens oppose) pending + delai dedie obligatoire.
    IF (LastDirection = 0) OR (ReqDirection = LastDirection) THEN
        CommandedDirection := ReqDirection;
        DirectionChangePending := FALSE;
    ELSE
        DirectionChangePending := TRUE;
    END_IF;
ELSIF (ReqDirection <> 0) AND (ReqDirection <> CommandedDirection) THEN
    // Inversion directe (sans passage au neutre) : pending + delai
    DirectionChangePending := TRUE;
ELSE
    DirectionChangePending := FALSE;
END_IF;

// Memorise le dernier sens non nul ADOPTE (pas la simple demande) : c'est ce sens qui
// sert de reference pour detecter une reprise opposee apres passage au neutre.
IF CommandedDirection <> 0 THEN
    LastDirection := CommandedDirection;
END_IF;

// === IMPLEMENTATION ===

IF NOT Enable THEN
    ShapedStep := 0;
    StepDelay(IN := FALSE);
    StepDelayElapsed := T#0s;
    RETURN;
END_IF;

// Temporisation : compte quand la cible est au-dessus du palier courant
StepDelay(
    IN := (TargetStep > ShapedStep) AND (ShapedStep > 0),
    PT := StepRampDelay
);
StepDelayElapsed := StepDelay.ET;

// Cadencement asymetrique : montee +1 cran / StepRampDelay, descente immediate
IF TargetStep = 0 THEN
    ShapedStep := 0;
ELSIF TargetStep < ShapedStep THEN
    ShapedStep := TargetStep;
ELSIF TargetStep > ShapedStep THEN
    IF ShapedStep = 0 THEN
        ShapedStep := 1;
    ELSIF StepDelay.Q THEN
        ShapedStep := ShapedStep + 1;
    END_IF;
END_IF;

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    ContactorMismatch := FALSE;
    MismatchActive := FALSE;
    MismatchTimer(IN := FALSE);
    RETURN;
END_IF;
{endregion}

{region "§2 Detection discordance"}
// 🔍 2. COHÉRENCE DES COMMANDES SÉCURITÉ — verifie que les commandes envoyees
// aux deux treuils sont identiques (sens et contacteurs).
// Filtre de 500ms pour tolerer les transitions et rampes.
IF NOT BypassGlobal THEN
    MismatchActive := SyncEnable AND (
        (RelayFwdM1 <> RelayFwdM2) OR
        (RelayRevM1 <> RelayRevM2) OR
        (Contactor1_M1 <> Contactor1_M2) OR
        (Contactor2_M1 <> Contactor2_M2) OR
        (Contactor3_M1 <> Contactor3_M2) OR
        (Contactor4_M1 <> Contactor4_M2)
    );
    MismatchTimer(IN := MismatchActive, PT := T#500ms);
    ContactorMismatch := MismatchTimer.Q;
ELSE
    ContactorMismatch := FALSE;
    MismatchActive := FALSE;
    MismatchTimer(IN := FALSE);
END_IF;
{endregion}

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    DeltaPosM := 0.0; SignedDeltaPosM := 0.0;
    SyncDeviationWarn := FALSE; SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
    RETURN;
END_IF;
ResetEdge(CLK := Reset);
{endregion}

{region "§2 Calcul ecart"}
// 📏 2. ÉCART M1/M2 — calculé en continu si les 2 treuils sont fiables (HomedAndReliable)
IF HomedAndReliableM1 AND HomedAndReliableM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;
{endregion}

{region "§3 Surveillance ecart 2 seuils"}
// 🔍 3. SURVEILLANCE ECART — 2 seuils (Warn/Fault).
// Warn (seuil 1) = INSTANTANE + LATCH : degrade le palier 1 des que l'ecart depasse,
// sans retard temporel ni oscillation (fidele a l'ancien SyncDegradedStep1).
// Fault (seuil 2) = filtre temporel pour le transitoire mecanique d'arret.
IF NOT BypassGlobal THEN
    WarnActive  := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncToleranceM);
    FaultActive := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncCriticalToleranceM);

    // Latch Warn : reste actif tant que la cause persiste OU que Reset n'a pas ete demande
    IF WarnActive THEN
        WarnLatched := TRUE;
    ELSIF ResetEdge.Q AND NOT WarnActive THEN
        WarnLatched := FALSE;
    END_IF;
    SyncDeviationWarn := WarnActive OR WarnLatched;

    DeviationFaultTimer(IN := FaultActive, PT := T#800ms);
    SyncDeviationFault := DeviationFaultTimer.Q;
ELSE
    SyncDeviationWarn := FALSE;
    SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
END_IF;
{endregion}
